CREATE TABLE public.billing_accounts(user_id uuid PRIMARY KEY,stripe_customer_id text NOT NULL UNIQUE);
GRANT SELECT ON public.billing_accounts TO authenticated;
GRANT ALL ON public.billing_accounts TO service_role;
ALTER TABLE public.billing_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY billing_owner_read ON public.billing_accounts FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.billing_subscriptions(stripe_subscription_id text PRIMARY KEY,user_id uuid NOT NULL REFERENCES public.billing_accounts(user_id) ON DELETE CASCADE,tier_id text NOT NULL REFERENCES public.ai_tiers(id) ON DELETE RESTRICT,stripe_price_id text NOT NULL,status text NOT NULL CHECK(status IN ('incomplete','incomplete_expired','trialing','active','past_due','canceled','unpaid','paused')),period_end timestamptz NOT NULL,cancel_at_period_end boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.billing_subscriptions TO authenticated;
GRANT ALL ON public.billing_subscriptions TO service_role;
ALTER TABLE public.billing_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscription_owner_read ON public.billing_subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.has_supporter_access(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR EXISTS(SELECT 1 FROM public.user_memberships WHERE user_id=_user_id AND tier_id='supporter' AND current_date BETWEEN starts_on AND ends_on) OR EXISTS(SELECT 1 FROM public.billing_subscriptions WHERE user_id=_user_id AND status='active' AND period_end>now()) $$;
CREATE OR REPLACE FUNCTION public.ai_quota_status(_user_id uuid) RETURNS TABLE(tier_id text,tier_name text,quota integer,used integer,is_blocked boolean,is_admin boolean,source text,period_start date,period_end date) LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE _start timestamptz := date_trunc('month',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'; _q public.user_ai_quotas%ROWTYPE; _t public.ai_tiers%ROWTYPE; _admin boolean:=public.has_role(_user_id,'admin'); BEGIN IF auth.uid() IS NULL OR (auth.uid()<>_user_id AND NOT public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO _q FROM public.user_ai_quotas q WHERE q.user_id=_user_id AND (q.valid_until IS NULL OR q.valid_until>=(now() AT TIME ZONE 'UTC')::date); IF FOUND THEN SELECT * INTO _t FROM public.ai_tiers WHERE id=_q.tier_id; ELSIF public.has_supporter_access(_user_id) THEN SELECT * INTO _t FROM public.ai_tiers WHERE id='supporter'; ELSE SELECT * INTO _t FROM public.ai_tiers WHERE ai_tiers.is_default LIMIT 1; END IF; RETURN QUERY SELECT _t.id,_t.name,CASE WHEN _admin THEN NULL WHEN coalesce(_q.is_blocked,false) THEN 0 WHEN _q.custom_quota IS NOT NULL THEN _q.custom_quota ELSE coalesce(_t.monthly_ai_quota,30) END,(SELECT count(*)::int FROM public.training_ai_history h WHERE h.user_id=_user_id AND h.generated_at>=_start),coalesce(_q.is_blocked,false),_admin,CASE WHEN _admin THEN 'admin' WHEN coalesce(_q.is_blocked,false) THEN 'blocked' WHEN _q.custom_quota IS NOT NULL THEN 'custom' ELSE 'tier' END,_start::date,(_start+interval '1 month')::date; END $$;
CREATE FUNCTION public.public_active_exercise_image(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.exercises WHERE is_active AND image_urls @> to_jsonb(ARRAY['storage:'||_path])) $$;
REVOKE ALL ON FUNCTION public.public_active_exercise_image(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_active_exercise_image(text) TO anon,authenticated,service_role;
ALTER POLICY public_catalogue_images ON storage.objects USING(bucket_id='exercise-images' AND public.public_active_exercise_image(name));
CREATE OR REPLACE FUNCTION public.erase_account_data(_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
DELETE FROM public.billing_accounts WHERE user_id=_user_id;
DELETE FROM public.log_entries WHERE user_id=_user_id;
DELETE FROM public.workouts WHERE user_id=_user_id;
DELETE FROM public.training_ai_history WHERE user_id=_user_id;
DELETE FROM public.training_profiles WHERE user_id=_user_id;
DELETE FROM public.training_goals WHERE user_id=_user_id;
DELETE FROM public.user_exercise_preferences WHERE user_id=_user_id;
DELETE FROM public.user_consents WHERE user_id=_user_id;
DELETE FROM public.user_ai_quotas WHERE user_id=_user_id;
DELETE FROM public.user_memberships WHERE user_id=_user_id;
DELETE FROM public.exercise_suggestions WHERE user_id=_user_id;
DELETE FROM public.support_messages WHERE user_id=_user_id;
DELETE FROM public.exercise_locations WHERE user_id=_user_id;
DELETE FROM public.admin_user_views WHERE actor_id=_user_id OR target_user_id=_user_id;
UPDATE public.exercises SET user_id=NULL WHERE user_id=_user_id;
DELETE FROM public.gyms WHERE user_id=_user_id AND NOT is_public;
UPDATE public.gyms SET user_id=NULL WHERE user_id=_user_id;
END $$;